class PriorityBoundedBuffer {
    PriorityQueue<Integer> queue = new PriorityQueue<>();
    int capacity;
    PriorityBoundedBuffer(int c) { capacity = c; }
    synchronized void put(int v) { while (queue.size()==capacity) { try { wait(); } catch (Exception e) {} } queue.add(v); notifyAll(); }
    synchronized int take() { while (queue.isEmpty()) { try { wait(); } catch (Exception e) {} } int v = queue.poll(); notifyAll(); return v; }
}
