class TaskProcessor {
    String state = "NEW";
    synchronized void setState(String s) { state = s; notifyAll(); }
    synchronized void waitForDone() throws InterruptedException { while (!"DONE".equals(state)) wait(); System.out.println("raport koncowy: " + state); }
}
TaskProcessor tp = new TaskProcessor();
Thread producent = new Thread(() -> {
    for (int i=0;i<5;i++) { try { Thread.sleep(50); } catch (Exception e) {} tp.setState("RUNNING"); }
    tp.setState("DONE");
});
Thread konsument = new Thread(() -> { try { tp.waitForDone(); } catch (Exception e) {} });
producent.start(); konsument.start();
producent.join(10_000); konsument.join(10_000);

class ShutdownableBuffer {
    Queue<Integer> queue = new LinkedList<>(); int capacity; boolean shutdownRequested = false;
    ShutdownableBuffer(int c) { capacity = c; }
    synchronized void put(int v) { while (queue.size()==capacity) { try { wait(); } catch (Exception e) {} } queue.add(v); notifyAll(); }
    synchronized void shutdown() { shutdownRequested = true; notifyAll(); }
    synchronized Integer take() { while (queue.isEmpty() && !shutdownRequested) { try { wait(); } catch (Exception e) {} } if (queue.isEmpty()) return null; int v = queue.poll(); notifyAll(); return v; }
}
